&lt;/a&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Invocation.html&quot; title=&quot;Invocation&quot;&gt;Invocation&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Convocation.html&quot; title=&quot;Convocation&quot;&gt;convocation&lt;/a&gt;) [voir texte] ; &lt;b&gt;Niveau&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;Dru&lt;/a&gt; 6  
&lt;b&gt;Temps d&#39;incantation&lt;/b&gt; 1 &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;  
&lt;b&gt;Composantes&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Composantes.html&quot; title=&quot;composantes&quot;&gt;V, G, F/FD&lt;/a&gt; (un morceau de tissu provenant du sac d&#39;un g&#233;ant)  
&lt;b&gt;Port&#233;e&lt;/b&gt; courte (7,50 m + 1,50 m/2 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveaux&lt;/a&gt;) (5 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt; + 1 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;/2 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveaux&lt;/a&gt;)  
&lt;b&gt;Effet&lt;/b&gt; un ou plusieurs &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-G&#233;ant.html&quot; title=&quot;G&#233;ant (sous-type)&quot;&gt;g&#233;ants&lt;/a&gt;  
&lt;b&gt;Dur&#233;e&lt;/b&gt; 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;/&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts.html#DUREE&quot; title=&quot;Pr&#233;sentation des sorts&quot;&gt;T&lt;/a&gt;)  
&lt;b&gt;Jet de sauvegarde&lt;/b&gt; aucun ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; non
&lt;hr&gt;
Ce sort fonctionne comme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-Dalli&#233;s-Naturels-Vi.html&quot; title=&quot;Convocation d&amp;#39;alli&#233;s naturels VI&quot;&gt;convocation d&#39;alli&#233;s naturels VI&lt;/a&gt;&lt;/i&gt;, except&#233; que son temps d&#39;incantation est plus court et que le personnage peut convoquer un &lt;a class=&quot;pagelink&quot; href=&quot;G&#233;ant-Des-Bois.html&quot; title=&quot;G&#233;ant, G&#233;ant des bois&quot;&gt;g&#233;ant des bois&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;G&#233;ant-Des-Collines.html&quot; title=&quot;G&#233;ant, G&#233;ant des collines&quot;&gt;des collines&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;G&#233;ant-Des-Grottes.html&quot; title=&quot;G&#233;ant, G&#233;ant des grottes&quot;&gt;des grottes&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;G&#233;ant-Des-Marais.html&quot; title=&quot;G&#233;ant, G&#233;ant des marais&quot;&gt;des marais&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;G&#233;ant-De-Pierre.html&quot; title=&quot;G&#233;ant, G&#233;ant de pierre&quot;&gt;de pierre&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;G&#233;ant-Des-Rivi&#232;res.html&quot; title=&quot;G&#233;ant, G&#233;ant des rivi&#232;res&quot;&gt;des rivi&#232;res&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;G&#233;ant-Des-Scories.html&quot; title=&quot;G&#233;ant, G&#233;ant des scories&quot;&gt;des scories&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h1 class=&quot;separator&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-Dalli&#233;s-G&#233;ants-Ii.html&quot; title=&quot;Convocation d&amp;#39;alli&#233;s g&#233;ants II&quot;&gt;Convocation d&#39;alli&#233;s g&#233;ants II&lt;/a&gt;&lt;a class=&quot;headeranchor&quot; id=&quot;_Convocation_dalli&#233;s_g&#233;ants_II__2&quot; href=&quot;#_Convocation_dalli&#233;s_g&#233;ants_II__2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&l